package com.shophighlighter;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("shophighlighter")
public interface ShopHighlighterConfig extends Config
{
	@ConfigItem(
		keyName = "borderWidth",
		name = "Border Width",
		description = "Width of the highlight border around items",
		position = 0
	)
	default int borderWidth()
	{
		return 2;
	}

	@ConfigItem(
		keyName = "fillHighlight",
		name = "Fill Highlight",
		description = "Fill the item background with the highlight color",
		position = 1
	)
	default boolean fillHighlight()
	{
		return true;
	}
}

package com.shophighlighter;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;

public class ShopHighlighterOverlay extends Overlay
{
	private final Client client;
	private final ShopHighlighterPlugin plugin;
	private final ShopHighlighterConfig config;

	@Inject
	private ShopHighlighterOverlay(Client client, ShopHighlighterPlugin plugin, ShopHighlighterConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(OverlayPriority.HIGH);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!plugin.isShopOpen())
		{
			return null;
		}

		List<ShopItem> items = plugin.getShopItems();
		if (items == null || items.isEmpty())
		{
			return null;
		}

		Widget shopContainer = findShopContainer();
		if (shopContainer == null || shopContainer.isHidden())
		{
			return null;
		}

		Widget[] children = shopContainer.getDynamicChildren();
		if (children == null)
		{
			children = shopContainer.getChildren();
		}
		if (children == null)
		{
			return null;
		}

		int borderWidth = Math.max(1, config.borderWidth());
		boolean fill = config.fillHighlight();

		for (ShopItem item : items)
		{
			if (!item.isHighlighted())
			{
				continue;
			}

			if (item.getSlot() < 0 || item.getSlot() >= children.length)
			{
				continue;
			}

			Widget itemWidget = children[item.getSlot()];
			if (itemWidget == null || itemWidget.isHidden())
			{
				continue;
			}

			Rectangle bounds = itemWidget.getBounds();
			if (bounds == null || bounds.width <= 0 || bounds.height <= 0)
			{
				continue;
			}

			Color fillColor = item.getHighlightColor();
			Color borderColor = item.getBorderColor();

			if (fill)
			{
				graphics.setColor(fillColor);
				graphics.fill(bounds);
			}

			graphics.setColor(borderColor);
			for (int i = 0; i < borderWidth; i++)
			{
				graphics.drawRect(
					bounds.x + i,
					bounds.y + i,
					bounds.width - (i * 2) - 1,
					bounds.height - (i * 2) - 1
				);
			}
		}

		return null;
	}

	private Widget findShopContainer()
	{
		int[][] candidates = {
			{300, 16},
			{300, 2},
			{300, 1},
			{301, 0},
			{301, 1},
			{302, 0},
		};

		for (int[] pair : candidates)
		{
			Widget w = client.getWidget(pair[0], pair[1]);
			if (w != null && !w.isHidden())
			{
				Widget[] dyn = w.getDynamicChildren();
				if (dyn != null && dyn.length > 0)
				{
					for (Widget child : dyn)
					{
						if (child != null && child.getItemId() > 0 && child.getItemId() != 6512)
						{
							return w;
						}
					}
				}
			}
		}

		for (int childId = 0; childId <= 20; childId++)
		{
			Widget w = client.getWidget(300, childId);
			if (w == null || w.isHidden())
			{
				continue;
			}
			Widget[] dyn = w.getDynamicChildren();
			if (dyn == null || dyn.length < 3)
			{
				continue;
			}
			for (Widget child : dyn)
			{
				if (child != null && child.getItemId() > 0 && child.getItemId() != 6512)
				{
					return w;
				}
			}
		}

		return null;
	}
}

package com.shophighlighter;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Font;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.util.ArrayList;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JColorChooser;
import javax.swing.JDialog;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import javax.swing.colorchooser.AbstractColorChooserPanel;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.ui.components.PluginErrorPanel;
import net.runelite.client.util.QuantityFormatter;

public class ShopHighlighterPanel extends PluginPanel
{
	private final ShopHighlighterPlugin plugin;
	private final ShopHighlighterConfig config;
	private final ItemManager itemManager;

	private final JPanel itemListPanel;
	private final PluginErrorPanel noShopPanel;
	private final JLabel titleLabel;

	public ShopHighlighterPanel(ShopHighlighterPlugin plugin, ShopHighlighterConfig config, ItemManager itemManager)
	{
		super(false);
		this.plugin = plugin;
		this.config = config;
		this.itemManager = itemManager;

		setBorder(new EmptyBorder(10, 10, 10, 10));
		setLayout(new BorderLayout(0, 10));
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		titleLabel = new JLabel("Shop Items");
		titleLabel.setForeground(Color.WHITE);
		titleLabel.setFont(titleLabel.getFont().deriveFont(Font.BOLD, 16f));
		titleLabel.setBorder(new EmptyBorder(0, 0, 8, 0));
		add(titleLabel, BorderLayout.NORTH);

		JPanel centerPanel = new JPanel();
		centerPanel.setLayout(new BoxLayout(centerPanel, BoxLayout.Y_AXIS));
		centerPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);

		noShopPanel = new PluginErrorPanel();
		noShopPanel.setContent("No shop open", "Open a shop to see its items here.");
		centerPanel.add(noShopPanel);

		itemListPanel = new JPanel();
		itemListPanel.setLayout(new BoxLayout(itemListPanel, BoxLayout.Y_AXIS));
		itemListPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		itemListPanel.setVisible(false);

		JScrollPane scrollPane = new JScrollPane(itemListPanel);
		scrollPane.setBackground(ColorScheme.DARK_GRAY_COLOR);
		scrollPane.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);
		scrollPane.setBorder(BorderFactory.createEmptyBorder());
		scrollPane.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
		scrollPane.getVerticalScrollBar().setPreferredSize(new Dimension(12, 0));

		centerPanel.add(scrollPane);
		add(centerPanel, BorderLayout.CENTER);

		JLabel hintLabel = new JLabel("<html><i>Check an item, click the color box to pick a color</i></html>");
		hintLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		hintLabel.setFont(hintLabel.getFont().deriveFont(11f));
		hintLabel.setBorder(new EmptyBorder(8, 0, 0, 0));
		add(hintLabel, BorderLayout.SOUTH);
	}

	public void updateItems(List<ShopItem> items)
	{
		SwingUtilities.invokeLater(() ->
		{
			itemListPanel.removeAll();

			if (items == null || items.isEmpty())
			{
				noShopPanel.setVisible(true);
				itemListPanel.setVisible(false);
				titleLabel.setText("Shop Items");
				revalidate();
				repaint();
				return;
			}

			noShopPanel.setVisible(false);
			itemListPanel.setVisible(true);
			titleLabel.setText("Shop Items (" + items.size() + ")");

			for (ShopItem item : items)
			{
				JPanel row = createItemRow(item);
				itemListPanel.add(row);
				itemListPanel.add(Box.createRigidArea(new Dimension(0, 4)));
			}

			itemListPanel.revalidate();
			itemListPanel.repaint();
			revalidate();
			repaint();
		});
	}

	private JPanel createItemRow(ShopItem item)
	{
		JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(ColorScheme.DARK_GRAY_COLOR, 1),
			new EmptyBorder(4, 6, 4, 6)
		));
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 40));
		row.setAlignmentX(Component.LEFT_ALIGNMENT);

		JCheckBox checkBox = new JCheckBox();
		checkBox.setSelected(item.isHighlighted());
		checkBox.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		checkBox.setFocusable(false);
		checkBox.addActionListener(e ->
		{
			item.setHighlighted(checkBox.isSelected());
			plugin.onHighlightToggled(item);
		});

		// Full color including alpha (for the dialog); opaque version for the button swatch
		Color fullColor = item.getHighlightColor();
		Color solid = new Color(fullColor.getRed(), fullColor.getGreen(), fullColor.getBlue());

		JButton colorBtn = new JButton();
		colorBtn.setPreferredSize(new Dimension(18, 18));
		colorBtn.setMinimumSize(new Dimension(18, 18));
		colorBtn.setMaximumSize(new Dimension(18, 18));
		colorBtn.setBackground(solid);
		colorBtn.setOpaque(true);
		colorBtn.setBorder(BorderFactory.createLineBorder(Color.GRAY, 1));
		colorBtn.setFocusable(false);
		colorBtn.setToolTipText("Click to change color");
		colorBtn.addActionListener(e ->
		{
			// Pass full color so transparency is preserved in the dialog
			Color chosen = showSimpleColorDialog(item.getHighlightColor(), item.getName());
			if (chosen != null)
			{
				plugin.onColorChanged(item, chosen);
				colorBtn.setBackground(new Color(chosen.getRed(), chosen.getGreen(), chosen.getBlue()));
			}
		});

		// Item image
		JLabel iconLabel = new JLabel();
		iconLabel.setPreferredSize(new Dimension(28, 28));
		iconLabel.setMinimumSize(new Dimension(28, 28));
		try
		{
			itemManager.getImage(item.getItemId(), item.getQuantity(), false).addTo(iconLabel);
		}
		catch (Exception ignored)
		{
			// Image may not be available yet
		}

		JPanel left = new JPanel(new FlowLayout(FlowLayout.LEFT, 5, 0));
		left.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		left.add(checkBox);
		left.add(colorBtn);
		left.add(iconLabel);

		JLabel nameLabel = new JLabel(item.getName());
		nameLabel.setForeground(Color.WHITE);
		nameLabel.setFont(nameLabel.getFont().deriveFont(Font.PLAIN, 12f));
		left.add(nameLabel);

		row.add(left, BorderLayout.WEST);

		JPanel right = new JPanel(new FlowLayout(FlowLayout.RIGHT, 6, 0));
		right.setBackground(ColorScheme.DARKER_GRAY_COLOR);

		if (item.getQuantity() > 0)
		{
			JLabel qtyLabel = new JLabel("x" + QuantityFormatter.formatNumber(item.getQuantity()));
			qtyLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			qtyLabel.setFont(qtyLabel.getFont().deriveFont(11f));
			right.add(qtyLabel);
		}

		row.add(right, BorderLayout.EAST);

		return row;
	}

	/**
	 * Color dialog defaulting to HSV, with Swatches available, and an item-slot preview.
	 */
	private Color showSimpleColorDialog(Color initial, String itemName)
	{
		// Ensure alpha is present so the transparency slider shows the saved value
		Color withAlpha = new Color(
			initial.getRed(),
			initial.getGreen(),
			initial.getBlue(),
			initial.getAlpha()
		);
		JColorChooser chooser = new JColorChooser(withAlpha);
		chooser.setColor(withAlpha);

		// Collect panels: put HSV/HSB first, then Swatches; drop the rest
		AbstractColorChooserPanel[] all = chooser.getChooserPanels();
		List<AbstractColorChooserPanel> ordered = new ArrayList<>();
		AbstractColorChooserPanel hsv = null;
		AbstractColorChooserPanel swatches = null;

		for (AbstractColorChooserPanel panel : all)
		{
			String name = panel.getDisplayName().toLowerCase();
			if (name.contains("hsv") || name.contains("hsb"))
			{
				hsv = panel;
			}
			else if (name.contains("swatch"))
			{
				swatches = panel;
			}
		}

		if (hsv != null)
		{
			ordered.add(hsv);
		}
		if (swatches != null)
		{
			ordered.add(swatches);
		}

		if (!ordered.isEmpty())
		{
			chooser.setChooserPanels(ordered.toArray(new AbstractColorChooserPanel[0]));
		}

		// Preview: solid swatch + example item slot with highlight
		JPanel preview = new JPanel(new FlowLayout(FlowLayout.LEFT, 12, 6));
		preview.setBorder(BorderFactory.createEmptyBorder(4, 6, 4, 6));

		JLabel selectedLabel = new JLabel("Selected:");
		JPanel solidSwatch = new JPanel();
		solidSwatch.setPreferredSize(new Dimension(28, 18));
		solidSwatch.setBackground(initial);
		solidSwatch.setBorder(BorderFactory.createLineBorder(Color.DARK_GRAY));

		JLabel exampleLabel = new JLabel("In shop:");
		ItemPreviewPanel itemPreview = new ItemPreviewPanel(initial);

		preview.add(selectedLabel);
		preview.add(solidSwatch);
		preview.add(Box.createHorizontalStrut(8));
		preview.add(exampleLabel);
		preview.add(itemPreview);

		chooser.setPreviewPanel(preview);

		chooser.getSelectionModel().addChangeListener(e ->
		{
			Color c = chooser.getColor();
			solidSwatch.setBackground(c);
			itemPreview.setPreviewColor(c);
		});

		final Color[] result = {null};

		JDialog dialog = JColorChooser.createDialog(
			this,
			"Color for " + itemName,
			true,
			chooser,
			e -> result[0] = chooser.getColor(),
			null
		);

		dialog.setVisible(true);
		return result[0];
	}

	/**
	 * Draws a small fake shop slot with the highlight applied.
	 */
	private static class ItemPreviewPanel extends JPanel
	{
		private Color previewColor;

		ItemPreviewPanel(Color color)
		{
			this.previewColor = color;
			setPreferredSize(new Dimension(36, 36));
			setBackground(new Color(62, 53, 41));
			setBorder(BorderFactory.createLineBorder(new Color(90, 80, 60)));
		}

		void setPreviewColor(Color color)
		{
			this.previewColor = color;
			repaint();
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			super.paintComponent(g);
			Graphics2D g2 = (Graphics2D) g;

			int pad = 2;
			int x = pad;
			int y = pad;
			int w = getWidth() - pad * 2 - 1;
			int h = getHeight() - pad * 2 - 1;

			g2.setColor(new Color(100, 90, 70));
			g2.fillRect(x + 6, y + 6, w - 12, h - 12);
			g2.setColor(new Color(140, 125, 95));
			g2.drawRect(x + 6, y + 6, w - 12, h - 12);

			// Use the chosen color including its transparency
			g2.setColor(previewColor);
			g2.fillRect(x, y, w, h);

			int a = previewColor.getAlpha();
			int borderAlpha = Math.min(255, Math.max(a, (int) (a * 1.8f + 40)));
			Color border = new Color(
				previewColor.getRed(),
				previewColor.getGreen(),
				previewColor.getBlue(),
				borderAlpha
			);
			g2.setColor(border);
			g2.drawRect(x, y, w, h);
			g2.drawRect(x + 1, y + 1, w - 2, h - 2);
		}
	}

	public void clear()
	{
		updateItems(null);
	}
}

package com.shophighlighter;

import com.google.inject.Provides;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ItemComposition;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.widgets.Widget;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
	name = "Shop Highlighter",
	description = "Shows a list of items in the currently opened shop and lets you toggle which ones to highlight",
	tags = {"shop", "highlight", "items", "overlay"}
)
public class ShopHighlighterPlugin extends Plugin
{
	private static final int[] SHOP_GROUP_IDS = {300, 301, 302, 303, 304};

	private static final Color DEFAULT_COLOR = new Color(0, 255, 0, 75);

	@Inject
	private Client client;

	@Inject
	private ShopHighlighterConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ShopHighlighterOverlay overlay;

	@Inject
	private ItemManager itemManager;

	@Getter
	private boolean shopOpen = false;

	@Getter
	private List<ShopItem> shopItems = new ArrayList<>();

	// itemId -> highlighted
	private final Map<Integer, Boolean> rememberedHighlights = new HashMap<>();
	// itemId -> custom color
	private final Map<Integer, Color> rememberedColors = new HashMap<>();


	private ShopHighlighterPanel panel;
	private NavigationButton navButton;

	@Override
	protected void startUp() throws Exception
	{
		overlayManager.add(overlay);

		panel = new ShopHighlighterPanel(this, config, itemManager);

		BufferedImage icon = createIcon();

		navButton = NavigationButton.builder()
			.tooltip("Shop Highlighter")
			.icon(icon)
			.priority(5)
			.panel(panel)
			.build();

		clientToolbar.addNavigation(navButton);

		log.info("Shop Highlighter started");
	}

	@Override
	protected void shutDown() throws Exception
	{
		overlayManager.remove(overlay);
		clientToolbar.removeNavigation(navButton);
		shopOpen = false;
		shopItems.clear();
		if (panel != null)
		{
			panel.clear();
		}
		log.info("Shop Highlighter stopped");
	}

	private BufferedImage createIcon()
	{
		BufferedImage image = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.setColor(new Color(40, 180, 80));
		g.fillRoundRect(2, 5, 12, 10, 3, 3);
		g.setColor(new Color(30, 140, 60));
		g.drawRoundRect(2, 5, 12, 10, 3, 3);
		g.setColor(new Color(255, 255, 255, 180));
		g.fillRect(5, 2, 2, 4);
		g.fillRect(9, 2, 2, 4);
		g.dispose();
		return image;
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		int groupId = event.getGroupId();
		for (int id : SHOP_GROUP_IDS)
		{
			if (groupId == id)
			{
				log.debug("Possible shop widget loaded: group {}", groupId);
				return;
			}
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		int groupId = event.getGroupId();
		for (int id : SHOP_GROUP_IDS)
		{
			if (groupId == id && shopOpen)
			{
				shopOpen = false;
				shopItems.clear();
				panel.clear();
				log.debug("Shop closed (group {})", groupId);
				return;
			}
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		scanShopItems();
	}

	private void scanShopItems()
	{
		Widget shopContainer = findShopContainer();

		if (shopContainer == null || shopContainer.isHidden())
		{
			if (shopOpen)
			{
				shopOpen = false;
				shopItems.clear();
				panel.clear();
			}
			return;
		}

		Widget[] children = shopContainer.getDynamicChildren();
		if (children == null || children.length == 0)
		{
			children = shopContainer.getChildren();
		}
		if (children == null || children.length == 0)
		{
			return;
		}

		List<ShopItem> newItems = new ArrayList<>();

		for (int i = 0; i < children.length; i++)
		{
			Widget child = children[i];
			if (child == null || child.isHidden())
			{
				continue;
			}

			int itemId = child.getItemId();
			if (itemId <= 0 || itemId == 6512)
			{
				continue;
			}

			ItemComposition composition = client.getItemDefinition(itemId);
			if (composition == null)
			{
				continue;
			}

			String name = composition.getName();
			if (name == null || name.equalsIgnoreCase("null") || name.isEmpty())
			{
				continue;
			}

			int quantity = child.getItemQuantity();

			Color color = rememberedColors.get(itemId);
			if (color == null)
			{
				color = DEFAULT_COLOR;
			}

			boolean highlighted = rememberedHighlights.getOrDefault(itemId, false);

			ShopItem shopItem = new ShopItem(itemId, i, name, 0, quantity, color);
			shopItem.setHighlighted(highlighted);
			newItems.add(shopItem);
		}

		if (newItems.isEmpty())
		{
			if (shopOpen)
			{
				shopOpen = false;
				shopItems.clear();
				panel.clear();
			}
			return;
		}

		// Detect any change worth refreshing the panel
		boolean changed = !shopOpen || newItems.size() != shopItems.size();
		if (!changed)
		{
			for (int i = 0; i < newItems.size(); i++)
			{
				ShopItem n = newItems.get(i);
				ShopItem o = shopItems.get(i);
				if (n.getItemId() != o.getItemId()
					|| n.getQuantity() != o.getQuantity()
					|| n.isHighlighted() != o.isHighlighted()
					|| !n.getHighlightColor().equals(o.getHighlightColor()))
				{
					changed = true;
					break;
				}
			}
		}

		// Carry over live object state (user may have just changed color/highlight this frame)
		if (!shopItems.isEmpty())
		{
			Map<Integer, ShopItem> oldById = new HashMap<>();
			for (ShopItem old : shopItems)
			{
				oldById.put(old.getItemId(), old);
			}
			for (ShopItem item : newItems)
			{
				ShopItem old = oldById.get(item.getItemId());
				if (old != null)
				{
					// Prefer in-memory object state (most recent user action)
					item.setHighlightColor(old.getHighlightColor());
					item.setHighlighted(old.isHighlighted());
				}
			}
		}

		shopOpen = true;
		shopItems = newItems;

		if (changed)
		{
			log.debug("Shop UI refresh ({} items)", shopItems.size());
			panel.updateItems(shopItems);
		}
	}

	private Widget findShopContainer()
	{
		int[][] candidates = {
			{300, 16},
			{300, 2},
			{300, 1},
			{301, 0},
			{301, 1},
			{302, 0},
		};

		for (int[] pair : candidates)
		{
			Widget w = client.getWidget(pair[0], pair[1]);
			if (w != null && !w.isHidden())
			{
				Widget[] dyn = w.getDynamicChildren();
				if (dyn != null && dyn.length > 0)
				{
					for (Widget child : dyn)
					{
						if (child != null && child.getItemId() > 0 && child.getItemId() != 6512)
						{
							return w;
						}
					}
				}
			}
		}

		for (int childId = 0; childId <= 20; childId++)
		{
			Widget w = client.getWidget(300, childId);
			if (w == null || w.isHidden())
			{
				continue;
			}
			Widget[] dyn = w.getDynamicChildren();
			if (dyn == null || dyn.length < 3)
			{
				continue;
			}
			for (Widget child : dyn)
			{
				if (child != null && child.getItemId() > 0 && child.getItemId() != 6512)
				{
					return w;
				}
			}
		}

		return null;
	}

	public void onHighlightToggled(ShopItem item)
	{
		rememberedHighlights.put(item.getItemId(), item.isHighlighted());

		if (item.isHighlighted() && !rememberedColors.containsKey(item.getItemId()))
		{
			item.setHighlightColor(DEFAULT_COLOR);
			rememberedColors.put(item.getItemId(), DEFAULT_COLOR);
		}

		// Keep list reference in sync and refresh panel immediately
		syncItemInList(item);
		panel.updateItems(shopItems);
	}

	public void onColorChanged(ShopItem item, Color newColor)
	{
		// Preserve full color including transparency from the color chooser
		item.setHighlightColor(newColor);
		rememberedColors.put(item.getItemId(), newColor);

		// Keep list reference in sync and refresh panel immediately
		syncItemInList(item);
		panel.updateItems(shopItems);
	}

	/** Ensure the shopItems list holds the same object the panel is editing */
	private void syncItemInList(ShopItem item)
	{
		for (int i = 0; i < shopItems.size(); i++)
		{
			if (shopItems.get(i).getItemId() == item.getItemId())
			{
				shopItems.set(i, item);
				return;
			}
		}
	}

	@Provides
	ShopHighlighterConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ShopHighlighterConfig.class);
	}
}

package com.shophighlighter;

import java.awt.Color;
import lombok.Data;
import lombok.EqualsAndHashCode;

@Data
@EqualsAndHashCode(of = {"itemId", "slot"})
public class ShopItem
{
	private final int itemId;
	private final int slot;
	private final String name;
	private final int price;
	private final int quantity;
	private boolean highlighted;
	private Color highlightColor;

	public ShopItem(int itemId, int slot, String name, int price, int quantity, Color highlightColor)
	{
		this.itemId = itemId;
		this.slot = slot;
		this.name = name;
		this.price = price;
		this.quantity = quantity;
		this.highlighted = false;
		this.highlightColor = highlightColor != null ? highlightColor : new Color(0, 255, 0, 75);
	}

	/** Border color derived from the fill color (stronger alpha for visibility) */
	public Color getBorderColor()
	{
		Color c = highlightColor;
		int a = c.getAlpha();
		// Border should be more opaque than fill, but still follow user transparency
		int borderAlpha = Math.min(255, Math.max(a, (int) (a * 1.8f + 40)));
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), borderAlpha);
	}
}

